    private MergeSort() {}

    public static void sort(int[] arr) {
        Objects.requireNonNull(arr, "arr must not be null");
        if (arr.length > 1) {
            mergeSort(arr, new int[(arr.length + 1) / 2], 0, arr.length - 1);
